\begin{align*}
\frac{\sqrt{8}+\sqrt{3}}{\sqrt{2}+\sqrt{3}}&=\frac{(\sqrt{8}+\sqrt{3})\cdot (\sqrt{2}-\sqrt{3})}{(\sqrt{2}+\sqrt{3})\cdot (\sqrt{2}-\sqrt{3})}\\
&=\frac{2\sqrt{2}-\sqrt{3} + 2\sqrt{3}-\sqrt{6}}{2-3}\\
&=\sqrt{6}+\sqrt{2}-2\sqrt{3}\\
\end{align*}

